    "ice.subtitle": "\u041D\u0430\u043B\u0430\u0448\u0442\u043E\u0432\u0443\u0454\u0442\u044C\u0441\u044F \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u043E - \u043D\u0456\u043A\u043E\u043B\u0438 \u043D\u0435 \u043F\u0435\u0440\u0435\u0434\u0430\u0454\u0442\u044C\u0441\u044F \u0441\u043F\u0456\u0432\u0440\u043E\u0437\u043C\u043E\u0432\u043D\u0438\u043A\u0443",
    "ice.intro": "\u0422\u0438\u043F\u043E\u0432\u043E SecureBit \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0454 \u043F\u0443\u0431\u043B\u0456\u0447\u043D\u0456 STUN-\u0441\u0435\u0440\u0432\u0435\u0440\u0438, \u0449\u043E\u0431 \u0443\u0437\u0433\u043E\u0434\u0438\u0442\u0438 \u043F\u0440\u044F\u043C\u0435 \u0437'\u0454\u0434\u043D\u0430\u043D\u043D\u044F. \u042F\u043A\u0449\u043E \u0442\u0440\u0438\u043C\u0430\u0454\u0442\u0435 \u0432\u043B\u0430\u0441\u043D\u0456, \u0432\u043A\u0430\u0436\u0456\u0442\u044C \u0441\u0432\u043E\u0457 STUN/TURN.",
    "ice.publicTitle": "\u041F\u0443\u0431\u043B\u0456\u0447\u043D\u0456 \u0441\u0435\u0440\u0432\u0435\u0440\u0438 (\u0442\u0438\u043F\u043E\u0432\u043E)",
    "ice.publicDesc": "\u0411\u0435\u0437 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F. \u041F\u0456\u0434\u0445\u043E\u0434\u0438\u0442\u044C \u0431\u0456\u043B\u044C\u0448\u043E\u0441\u0442\u0456.",
    "ice.customTitle": "\u0412\u043B\u0430\u0441\u043D\u0456 STUN/TURN-\u0441\u0435\u0440\u0432\u0435\u0440\u0438",
    "ice.customDesc": "\u0414\u043E {max} \u0441\u0435\u0440\u0432\u0435\u0440\u0456\u0432.",
    "ice.turnNote": "TURN-relay \u0431\u0430\u0447\u0438\u0442\u044C IP \u043E\u0431\u043E\u0445 \u0441\u0442\u043E\u0440\u0456\u043D \u0456 \u0440\u0438\u0442\u043C \u0442\u0440\u0430\u0444\u0456\u043A\u0443 - \u0430\u043B\u0435 \u043D\u0456\u043A\u043E\u043B\u0438 \u0432\u043C\u0456\u0441\u0442 \u043F\u043E\u0432\u0456\u0434\u043E\u043C\u043B\u0435\u043D\u044C, \u044F\u043A\u0438\u0439 \u043B\u0438\u0448\u0430\u0454\u0442\u044C\u0441\u044F \u0437\u0430\u0448\u0438\u0444\u0440\u043E\u0432\u0430\u043D\u0438\u043C \u043D\u0430\u0441\u043A\u0440\u0456\u0437\u043D\u043E. \u041A\u0440\u0430\u0449\u0435 ",
    "ice.turnNoteTls": " (TLS).",
    "ice.test": "\u041F\u0435\u0440\u0435\u0432\u0456\u0440\u0438\u0442\u0438 \u0441\u0435\u0440\u0432\u0435\u0440\u0438",
    "ice.testing": "\u041F\u0435\u0440\u0435\u0432\u0456\u0440\u043A\u0430\u2026",
    "ice.relayTitle": "\u0420\u0435\u0436\u0438\u043C \u043B\u0438\u0448\u0435 \u0447\u0435\u0440\u0435\u0437 relay",
    "ice.relayBadge": "\u041C\u0410\u041A\u0421\u0418\u041C\u0423\u041C \u041F\u0420\u0418\u0412\u0410\u0422\u041D\u041E\u0421\u0422\u0406",
    "ice.relayDesc": "\u041F\u0440\u043E\u043F\u0443\u0441\u043A\u0430\u0454 \u0432\u0435\u0441\u044C \u0442\u0440\u0430\u0444\u0456\u043A \u0447\u0435\u0440\u0435\u0437 TURN, \u0442\u043E\u0436 \u0441\u043F\u0456\u0432\u0440\u043E\u0437\u043C\u043E\u0432\u043D\u0438\u043A \u043D\u0456\u043A\u043E\u043B\u0438 \u043D\u0435 \u043F\u043E\u0431\u0430\u0447\u0438\u0442\u044C \u0432\u0430\u0448\u043E\u0457 IP. \u041F\u043E\u0442\u0440\u0456\u0431\u0435\u043D TURN-\u0441\u0435\u0440\u0432\u0435\u0440.",
    "ice.relayWarning": "\u0420\u0435\u0436\u0438\u043C \u043B\u0438\u0448\u0435 \u0447\u0435\u0440\u0435\u0437 relay \u0443\u0432\u0456\u043C\u043A\u043D\u0435\u043D\u043E, \u0430\u043B\u0435 TURN-\u0441\u0435\u0440\u0432\u0435\u0440 \u043D\u0435 \u0432\u043A\u0430\u0437\u0430\u043D\u043E. \u0417'\u0454\u0434\u043D\u0430\u043D\u043D\u044F \u043D\u0435 \u0437\u043C\u043E\u0436\u0435 \u043F\u043E\u0447\u0430\u0442\u0438\u0441\u044F.",
    "ice.persist": "\u0417\u0431\u0435\u0440\u0435\u0433\u0442\u0438 \u043D\u0430 \u0446\u044C\u043E\u043C\u0443 \u043F\u0440\u0438\u0441\u0442\u0440\u043E\u0457",
    "ice.persistDesc": "\u0417\u0431\u0435\u0440\u0456\u0433\u0430\u0454\u0442\u044C\u0441\u044F \u0437\u0430\u0448\u0438\u0444\u0440\u043E\u0432\u0430\u043D\u043E \u0432 \u0446\u044C\u043E\u043C\u0443 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0456. \u041B\u0438\u0448\u0456\u0442\u044C \u0432\u0438\u043C\u043A\u043D\u0435\u043D\u0438\u043C, \u0449\u043E\u0431 \u0434\u0456\u044F\u043B\u043E \u043B\u0438\u0448\u0435 \u0432 \u0446\u044C\u043E\u043C\u0443 \u0441\u0435\u0430\u043D\u0441\u0456.",
    "ice.forget": "\u0417\u0430\u0431\u0443\u0442\u0438 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043D\u0435",
    "ice.cancel": "\u0421\u043A\u0430\u0441\u0443\u0432\u0430\u0442\u0438",
