    "update.stepReload": "\u041F\u0435\u0440\u0435\u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0435\u043D\u043D\u044F \u0437\u0430\u0441\u0442\u043E\u0441\u0443\u043D\u043A\u0443\u2026",
    "update.error": "\u041F\u043E\u043C\u0438\u043B\u043A\u0430 \u043E\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044F. \u041F\u0435\u0440\u0435\u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0442\u0435 \u0441\u0442\u043E\u0440\u0456\u043D\u043A\u0443 \u0432\u0440\u0443\u0447\u043D\u0443 (Ctrl+F5 \u0430\u0431\u043E Cmd+Shift+R)",
    "update.confirmSkip": "\u0414\u043E\u0441\u0442\u0443\u043F\u043D\u0430 \u043D\u043E\u0432\u0430 \u0432\u0435\u0440\u0441\u0456\u044F. \u041E\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044F \u0440\u0435\u043A\u043E\u043C\u0435\u043D\u0434\u043E\u0432\u0430\u043D\u0435 \u0437\u0430\u0434\u043B\u044F \u0431\u0435\u0437\u043F\u0435\u043A\u0438 \u0442\u0430 \u0441\u0442\u0430\u0431\u0456\u043B\u044C\u043D\u043E\u0441\u0442\u0456. \u041F\u0440\u043E\u0434\u043E\u0432\u0436\u0438\u0442\u0438 \u0431\u0435\u0437 \u043E\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044F?",
    "offline.backOnline": "\u0417\u043D\u043E\u0432\u0443 \u043E\u043D\u043B\u0430\u0439\u043D",
    "offline.mode": "\u0420\u0435\u0436\u0438\u043C \u043E\u0444\u043B\u0430\u0439\u043D",
    "offline.dismiss": "\u0417\u0430\u043A\u0440\u0438\u0442\u0438",
    "offline.lostTitle": "\u0417'\u0454\u0434\u043D\u0430\u043D\u043D\u044F \u0432\u0442\u0440\u0430\u0447\u0435\u043D\u043E",
    "offline.lostDesc": "SecureBit \u043F\u0440\u0430\u0446\u044E\u0454 \u043E\u0444\u043B\u0430\u0439\u043D. \u0414\u0435\u0449\u043E \u043E\u0431\u043C\u0435\u0436\u0435\u043D\u043E, \u0430\u043B\u0435 \u0432\u0430\u0448\u0456 \u0434\u0430\u043D\u0456 \u0432 \u0431\u0435\u0437\u043F\u0435\u0446\u0456.",
    "offline.point1": "\u0412\u0430\u0448 \u0441\u0435\u0430\u043D\u0441 \u0456 \u043A\u043B\u044E\u0447\u0456 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043D\u043E",
    "offline.point2": "\u0416\u043E\u0434\u043D\u0438\u0445 \u0434\u0430\u043D\u0438\u0445 \u043D\u0430 \u0441\u0435\u0440\u0432\u0435\u0440\u0430\u0445",
    "offline.point3": "\u041F\u043E\u0432\u0456\u0434\u043E\u043C\u043B\u0435\u043D\u043D\u044F \u0439 \u0444\u0430\u0439\u043B\u0438 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0456\u0437\u0443\u044E\u0442\u044C\u0441\u044F \u043F\u0456\u0441\u043B\u044F \u0432\u0456\u0434\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044F \u0437\u0432'\u044F\u0437\u043A\u0443",
    "offline.continue": "\u041F\u0440\u043E\u0434\u043E\u0432\u0436\u0438\u0442\u0438 \u043E\u0444\u043B\u0430\u0439\u043D",
    "offline.restoredTitle": "\u041A\u043E\u043B\u0438 \u0437\u0432'\u044F\u0437\u043E\u043A \u0432\u0456\u0434\u043D\u043E\u0432\u0438\u0442\u044C\u0441\u044F",
    "offline.restoredDesc": "\u041E\u0431\u0440\u0438\u0432 \u0437\u0432'\u044F\u0437\u043A\u0443 \u043D\u0456\u0447\u043E\u0433\u043E \u043D\u0435 \u043A\u043E\u0448\u0442\u0443\u0454. SecureBit \u0441\u043A\u043B\u0430\u0434\u0430\u0454 \u0432\u0441\u0435 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u043E \u0432 \u0447\u0435\u0440\u0433\u0443 \u0439 \u0432\u0456\u0434\u043D\u043E\u0432\u043B\u044E\u0454 \u0437\u0430\u0448\u0438\u0444\u0440\u043E\u0432\u0430\u043D\u0438\u0439 \u0441\u0435\u0430\u043D\u0441, \u0449\u043E\u0439\u043D\u043E \u0432\u0438 \u0437\u043D\u043E\u0432\u0443 \u043E\u043D\u043B\u0430\u0439\u043D.",
    "offline.r1Title": "\u0412\u0430\u0448\u0456 \u043F\u043E\u0432\u0456\u0434\u043E\u043C\u043B\u0435\u043D\u043D\u044F \u0434\u0456\u0439\u0434\u0443\u0442\u044C",
    "offline.r1Desc": "\u0423\u0441\u0435, \u0449\u043E \u0432\u0438 \u043D\u0430\u043F\u0438\u0441\u0430\u043B\u0438 \u043E\u0444\u043B\u0430\u0439\u043D, \u043D\u0430\u0434\u0441\u0438\u043B\u0430\u0454\u0442\u044C\u0441\u044F \u0441\u043F\u0456\u0432\u0440\u043E\u0437\u043C\u043E\u0432\u043D\u0438\u043A\u0443 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u043D\u043E.",
    "offline.r2Title": "\u0424\u0430\u0439\u043B\u0438 \u0434\u043E\u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0430\u0442\u044C\u0441\u044F",
    "offline.r2Desc": "\u041F\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u043D\u043D\u044F \u043F\u0440\u043E\u0434\u043E\u0432\u0436\u0438\u0442\u044C\u0441\u044F \u0437 \u043C\u0456\u0441\u0446\u044F \u0437\u0443\u043F\u0438\u043D\u043A\u0438 - \u043D\u0430\u0434\u0441\u0438\u043B\u0430\u0442\u0438 \u0437\u0430\u043D\u043E\u0432\u043E \u043D\u0435 \u0442\u0440\u0435\u0431\u0430.",
    "offline.r3Title": "\u0407\u0445\u043D\u0456 \u043F\u043E\u0432\u0456\u0434\u043E\u043C\u043B\u0435\u043D\u043D\u044F \u0439 \u0444\u0430\u0439\u043B\u0438 \u043D\u0430\u0434\u0456\u0439\u0434\u0443\u0442\u044C",
    "offline.r3Desc": "\u0423\u0441\u0435, \u0449\u043E \u0441\u043F\u0456\u0432\u0440\u043E\u0437\u043C\u043E\u0432\u043D\u0438\u043A \u043D\u0430\u0434\u0456\u0441\u043B\u0430\u0432 \u043F\u0456\u0434 \u0447\u0430\u0441 \u043F\u0435\u0440\u0435\u0440\u0432\u0438, \u043D\u0430\u0434\u0456\u0439\u0434\u0435 \u0432\u0430\u043C \u043F\u043E \u043F\u043E\u0440\u044F\u0434\u043A\u0443.",
    "offline.r4Title": "\u041D\u0456\u0447\u043E\u0433\u043E \u043D\u0435 \u0432\u0442\u0440\u0430\u0447\u0430\u0454\u0442\u044C\u0441\u044F",
    "offline.r4Desc": "\u041F\u0456\u0441\u043B\u044F \u0432\u0456\u0434\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044F \u0437\u0432'\u044F\u0437\u043A\u0443 \u0440\u043E\u0437\u0440\u0438\u0432\u0443 \u043D\u0435 \u043B\u0438\u0448\u0430\u0454\u0442\u044C\u0441\u044F - \u0440\u043E\u0437\u043C\u043E\u0432\u0430 \u0442\u0440\u0438\u0432\u0430\u0454 \u0440\u0456\u0432\u043D\u043E \u0437 \u0442\u043E\u0433\u043E \u043C\u0456\u0441\u0446\u044F, \u0434\u0435 \u0441\u043F\u0438\u043D\u0438\u043B\u0430\u0441\u044F.",
    "offline.gotIt": "\u0417\u0440\u043E\u0437\u0443\u043C\u0456\u043B\u043E",
    "qr.showTitle": "\u041F\u043E\u043A\u0430\u0437\u0430\u0442\u0438 QR-\u043A\u043E\u0434",
