    "chat.decrypted": "\u0420\u043E\u0437\u0448\u0438\u0444\u0440\u043E\u0432\u0430\u043D\u043E",
    "chat.encryptedOnDevice": "\u0417\u0430\u0448\u0438\u0444\u0440\u043E\u0432\u0430\u043D\u043E \u043D\u0430 \u0432\u0430\u0448\u043E\u043C\u0443 \u043F\u0440\u0438\u0441\u0442\u0440\u043E\u0457",
