    "chat.closeMenu": "\u0417\u0430\u043A\u0440\u0438\u0442\u0438 \u043C\u0435\u043D\u044E",
    "chat.newChat": "\u041D\u043E\u0432\u0438\u0439 \u0447\u0430\u0442",
    "chat.newGroup": "\u041D\u043E\u0432\u0430 \u0433\u0440\u0443\u043F\u0430",
    "chat.createGroup": "\u0421\u0442\u0432\u043E\u0440\u0438\u0442\u0438 \u0433\u0440\u0443\u043F\u0443",
