    "chat.secureChat": "\u0417\u0430\u0445\u0438\u0449\u0435\u043D\u0438\u0439 \u0447\u0430\u0442",
    "chat.nameThis": "\u041D\u0430\u0437\u0432\u0456\u0442\u044C \u0446\u0435\u0439 \u0447\u0430\u0442",
    "chat.rename": "\u041F\u0435\u0440\u0435\u0439\u043C\u0435\u043D\u0443\u0432\u0430\u0442\u0438 \u0447\u0430\u0442 (\u043B\u0438\u0448\u0435 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u043E)",
    "chat.renameHint": "\u0414\u0432\u0456\u0447\u0456 \u043A\u043B\u0430\u0446\u043D\u0456\u0442\u044C, \u0449\u043E\u0431 \u043F\u0435\u0440\u0435\u0439\u043C\u0435\u043D\u0443\u0432\u0430\u0442\u0438",
    "chat.localLabel": "\u041B\u043E\u043A\u0430\u043B\u044C\u043D\u0430 \u043D\u0430\u0437\u0432\u0430 \xB7 \u0437\u0431\u0435\u0440\u0456\u0433\u0430\u0454\u0442\u044C\u0441\u044F \u043B\u0438\u0448\u0435 \u043D\u0430 \u0446\u044C\u043E\u043C\u0443 \u043F\u0440\u0438\u0441\u0442\u0440\u043E\u0457",
    "chat.setStatus": "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0456\u0442\u044C \u0441\u0432\u0456\u0439 \u0441\u0442\u0430\u0442\u0443\u0441",
    "chat.yourStatusPrefix": "\u0412\u0430\u0448 \u0441\u0442\u0430\u0442\u0443\u0441 - ",
