    "roadmap.r1.title": "\u041D\u0430\u0447\u0430\u043B\u043E \u0440\u0430\u0437\u0440\u0430\u0431\u043E\u0442\u043A\u0438",
    "roadmap.r1.sub": "\u0418\u0434\u0435\u044F, \u043F\u0440\u043E\u0442\u043E\u0442\u0438\u043F \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430 \u0438\u043D\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043A\u0442\u0443\u0440\u044B",
    "roadmap.r1.date": "\u041D\u0430\u0447\u0430\u043B\u043E 2025",
    "roadmap.r1.features": [
      "\u0424\u043E\u0440\u043C\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0435 \u043A\u043E\u043D\u0446\u0435\u043F\u0446\u0438\u0438 \u0438 \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u0439",
      "\u0412\u044B\u0431\u043E\u0440 \u0441\u0442\u0435\u043A\u0430: WebRTC, P2P, \u043A\u0440\u0438\u043F\u0442\u043E\u0433\u0440\u0430\u0444\u0438\u044F",
      "\u041F\u0435\u0440\u0432\u044B\u0435 \u043F\u0440\u043E\u0442\u043E\u0442\u0438\u043F\u044B \u043E\u0431\u043C\u0435\u043D\u0430 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F\u043C\u0438",
      "\u0421\u043E\u0437\u0434\u0430\u043D\u0438\u0435 \u0440\u0435\u043F\u043E\u0437\u0438\u0442\u043E\u0440\u0438\u044F \u0438 CI",
      "\u0411\u0430\u0437\u043E\u0432\u0430\u044F \u0430\u0440\u0445\u0438\u0442\u0435\u043A\u0442\u0443\u0440\u0430 \u0448\u0438\u0444\u0440\u043E\u0432\u0430\u043D\u0438\u044F",
      "\u0414\u0438\u0437\u0430\u0439\u043D UX/UI"
    ],
    "roadmap.r2.title": "\u0410\u043B\u044C\u0444\u0430-\u0432\u0435\u0440\u0441\u0438\u044F",
    "roadmap.r2.sub": "\u041F\u0435\u0440\u0432\u0430\u044F \u043F\u0443\u0431\u043B\u0438\u0447\u043D\u0430\u044F \u0430\u043B\u044C\u0444\u0430: \u0431\u0430\u0437\u043E\u0432\u044B\u0439 \u0447\u0430\u0442 \u0438 \u043E\u0431\u043C\u0435\u043D \u043A\u043B\u044E\u0447\u0430\u043C\u0438",
    "roadmap.r2.date": "\u0412\u0435\u0441\u043D\u0430 2025",
    "roadmap.r2.features": [
      "\u0411\u0430\u0437\u043E\u0432\u044B\u0439 \u043E\u0431\u043C\u0435\u043D \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F\u043C\u0438 P2P \u0447\u0435\u0440\u0435\u0437 WebRTC",
      "\u041F\u0440\u043E\u0441\u0442\u043E\u0435 \u0441\u043A\u0432\u043E\u0437\u043D\u043E\u0435 \u0448\u0438\u0444\u0440\u043E\u0432\u0430\u043D\u0438\u0435 (\u0434\u0435\u043C\u043E\u043D\u0441\u0442\u0440\u0430\u0446\u0438\u043E\u043D\u043D\u0430\u044F \u0441\u0445\u0435\u043C\u0430)",
      "\u0421\u0442\u0430\u0431\u0438\u043B\u044C\u043D\u044B\u0439 \u0441\u0438\u0433\u043D\u0430\u043B\u0438\u043D\u0433 \u0438 \u043F\u0435\u0440\u0435\u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435",
      "\u041C\u0438\u043D\u0438\u043C\u0430\u043B\u044C\u043D\u044B\u0439 \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441 \u0434\u043B\u044F \u0442\u0435\u0441\u0442\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u044F",
      "\u0421\u0431\u043E\u0440 \u043E\u0442\u0437\u044B\u0432\u043E\u0432 \u043E\u0442 \u043F\u0435\u0440\u0432\u044B\u0445 \u0442\u0435\u0441\u0442\u0438\u0440\u043E\u0432\u0449\u0438\u043A\u043E\u0432"
    ],
    "roadmap.r3.title": "\u0423\u0441\u0438\u043B\u0435\u043D\u043D\u0430\u044F \u0437\u0430\u0449\u0438\u0442\u0430",
