    "roadmap.r9.date": "\u0421\u0435\u0439\u0447\u0430\u0441",
    "roadmap.r9.features": [
      "\u0413\u0440\u0443\u043F\u043F\u043E\u0432\u044B\u0435 \u0447\u0430\u0442\u044B P2P \u0434\u043E 8 \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432",
      "\u0414\u043E\u0441\u0442\u0430\u0432\u043A\u0430 \u043F\u043E \u0441\u0435\u0442\u0438 \u0441 \u043F\u043E\u0434\u043F\u0438\u0441\u0430\u043D\u043D\u044B\u043C relay \u043A\u0430\u043A \u0437\u0430\u043F\u0430\u0441\u043D\u044B\u043C \u043F\u0443\u0442\u0451\u043C",
      "\u041E\u0434\u0438\u043D \u043A\u043E\u0434 \u0431\u0435\u0437\u043E\u043F\u0430\u0441\u043D\u043E\u0441\u0442\u0438 \u0433\u0440\u0443\u043F\u043F\u044B, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0441\u0432\u0435\u0440\u044F\u044E\u0442 \u0432\u0441\u0435",
      "\u0426\u0435\u0440\u0435\u043C\u043E\u043D\u0438\u044F \xAB\u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u043E, \u043F\u043E\u0442\u043E\u043C \u0440\u0430\u0441\u043A\u0440\u044B\u0442\u0438\u0435\xBB \u043F\u0440\u043E\u0442\u0438\u0432 \u043F\u043E\u0434\u0431\u043E\u0440\u0430 \u043A\u043E\u0434\u043E\u0432",
      "\u0421\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0435 \u043A\u043B\u044E\u0447\u0438 \u043B\u0438\u0447\u043D\u043E\u0441\u0442\u0438 \u0432 \u0433\u0440\u0443\u043F\u043F\u0435, \u044D\u0444\u0435\u043C\u0435\u0440\u043D\u044B\u0435 \u043F\u043E \u0437\u0430\u043C\u044B\u0441\u043B\u0443",
      "\u041F\u043E\u0434\u043F\u0438\u0441\u0430\u043D\u043D\u043E\u0435 \u0447\u043B\u0435\u043D\u0441\u0442\u0432\u043E \u0441 \u0443\u043F\u043E\u0440\u044F\u0434\u043E\u0447\u0438\u0432\u0430\u043D\u0438\u0435\u043C \u043F\u043E \u044D\u043F\u043E\u0445\u0430\u043C",
      "\u041F\u043E\u0434\u043F\u0438\u0441\u0430\u043D\u043D\u044B\u0435 \u0441\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F - \u0440\u0430\u0441\u0445\u043E\u0436\u0434\u0435\u043D\u0438\u0435 \u0432 \u0441\u0442\u0435\u043D\u043E\u0433\u0440\u0430\u043C\u043C\u0435 \u043C\u043E\u0436\u043D\u043E \u0434\u043E\u043A\u0430\u0437\u0430\u0442\u044C",
      "\u0411\u0435\u0437 \u0441\u0435\u0440\u0432\u0435\u0440\u0430, \u0431\u0435\u0437 \u043E\u0431\u0449\u0435\u0433\u043E \u043A\u043B\u044E\u0447\u0430 \u0433\u0440\u0443\u043F\u043F\u044B, \u0431\u0435\u0437 \u0438\u0441\u0442\u043E\u0440\u0438\u0438"
    ],
