    "ice.publicDesc": "\uC124\uC815\uC774 \uD544\uC694 \uC5C6\uC2B5\uB2C8\uB2E4. \uB300\uBD80\uBD84\uC5D0\uAC8C \uCDA9\uBD84\uD569\uB2C8\uB2E4.",
