    "ice.relayDesc": "\uBAA8\uB4E0 \uD2B8\uB798\uD53D\uC744 TURN\uC73C\uB85C \uBCF4\uB0B4 \uC0C1\uB300\uAC00 \uC5EC\uB7EC\uBD84\uC758 IP\uB97C \uACB0\uCF54 \uC54C \uC218 \uC5C6\uAC8C \uD569\uB2C8\uB2E4. TURN \uC11C\uBC84\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.",
    "ice.relayWarning": "\uB9B4\uB808\uC774 \uC804\uC6A9 \uBAA8\uB4DC\uAC00 \uCF1C\uC838 \uC788\uC9C0\uB9CC TURN \uC11C\uBC84\uAC00 \uC124\uC815\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uC5F0\uACB0\uC744 \uC2DC\uC791\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.",
