    "ice.persistDesc": "\uC774 \uBE0C\uB77C\uC6B0\uC800\uC5D0 \uC554\uD638\uD654\uB418\uC5B4 \uC800\uC7A5\uB429\uB2C8\uB2E4. \uAEBC\uB450\uBA74 \uC774\uBC88 \uC138\uC158\uC5D0\uB9CC \uC801\uC6A9\uB429\uB2C8\uB2E4.",
