    "flow.sendTheResponse": "\uC751\uB2F5 \uBCF4\uB0B4\uAE30",
    "flow.pasteOrWrite": "\uCF54\uB4DC\uB97C \uBD99\uC5EC\uB123\uAC70\uB098 \uC785\uB825\uD558\uC138\uC694\u2026",
    "flow.processingInvitation": "\uC548\uC804\uD55C \uCD08\uB300\uB97C \uCC98\uB9AC\uD558\uB294 \uC911\u2026",
    "flow.processingResponse": "\uC548\uC804\uD55C \uC751\uB2F5\uC744 \uCC98\uB9AC\uD558\uB294 \uC911\u2026",
