    "flow.channelEstablished": "\uC548\uC804\uD55C \uCC44\uB110\uC774 \uB9CC\uB4E4\uC5B4\uC84C\uC2B5\uB2C8\uB2E4",
    "flow.channelReady": "\uC548\uC804\uD55C \uCC44\uB110\uC774 \uC900\uBE44\uB418\uC5C8\uC2B5\uB2C8\uB2E4",
    "flow.restoring": "\uC5F0\uACB0\uC744 \uB418\uC0B4\uB9AC\uB294 \uC911\u2026",
    "flow.invitationCaptured": "\uCD08\uB300\uB97C \uC77D\uC5C8\uC2B5\uB2C8\uB2E4.",
    "err.needInvitation": "\uC0C1\uB300\uAC00 \uC900 \uCD08\uB300 \uCF54\uB4DC\uB97C \uBD99\uC5EC\uB123\uC5B4\uC57C \uD569\uB2C8\uB2E4.",
    "err.needResponse": "\uC0C1\uB300\uAC00 \uC900 \uC751\uB2F5 \uCF54\uB4DC\uB97C \uBD99\uC5EC\uB123\uC5B4\uC57C \uD569\uB2C8\uB2E4.",
    "err.responseFormat": "\uC751\uB2F5 \uD615\uC2DD\uC774 \uC62C\uBC14\uB974\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4 - \uCF54\uB4DC\uB97C \uD655\uC778\uD558\uC138\uC694",
    "err.responseNoKey": "\uC751\uB2F5 \uCF54\uB4DC\uAC00 \uC62C\uBC14\uB974\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4 - \uC554\uD638 \uD0A4\uAC00 \uC5C6\uAC70\uB098 \uC190\uC0C1\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uCF54\uB4DC\uB97C \uD655\uC778\uD55C \uB4A4 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.",
    "err.responseNoSignKey": "\uC751\uB2F5 \uCF54\uB4DC\uAC00 \uC62C\uBC14\uB974\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4 - \uC11C\uBA85 \uD655\uC778 \uD0A4\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4. \uCF54\uB4DC\uB97C \uD655\uC778\uD55C \uB4A4 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.",
    "err.responseOutdated": "\uC751\uB2F5 \uB370\uC774\uD130\uAC00 \uC624\uB798\uB418\uC5C8\uC2B5\uB2C8\uB2E4 - \uC0C8 \uCD08\uB300\uB97C \uC0AC\uC6A9\uD558\uC138\uC694",
    "err.setupError": "\uC5F0\uACB0\uC744 \uB9FA\uB294 \uC911 \uC624\uB958\uAC00 \uB0AC\uC2B5\uB2C8\uB2E4",
    "err.notReady": "\uC5F0\uACB0\uC774 \uC544\uC9C1 \uC900\uBE44\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4",
    "err.securityBreach": "\uBCF4\uC548 \uCE68\uD574\uAC00 \uAC10\uC9C0\uB418\uC5B4 \uC5F0\uACB0\uC744 \uAC70\uBD80\uD588\uC2B5\uB2C8\uB2E4",
    "err.securityValidation": "\uBCF4\uC548 \uAC80\uC99D\uC5D0 \uC2E4\uD328\uD588\uC2B5\uB2C8\uB2E4 - \uACF5\uACA9\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4",
    "err.retiredQr": "\uC774 QR\uC740 \uB354 \uC774\uC0C1 \uC4F0\uC9C0 \uC54A\uB294 \uD615\uC2DD\uC774\uB77C \uCD08\uB300\uB97C \uC804\uB2EC\uD558\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4. \uC0C1\uB300\uC5D0\uAC8C \uC0C8\uB85C \uB9CC\uB4E4\uC5B4 \uB2EC\uB77C\uACE0 \uD558\uAC70\uB098 \uBCF5\uC0AC\xB7\uBD99\uC5EC\uB123\uAE30\uB97C \uC4F0\uC138\uC694.",
    "err.compressedQrNote": "\uC555\uCD95\uB41C QR\uC740 \uAC04\uACB0\uD568\uC744 \uC704\uD574 SDP\uB97C \uC0DD\uB7B5\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC5F0\uACB0\uC5D0 \uC2E4\uD328\uD558\uBA74 \uBCF5\uC0AC\xB7\uBD99\uC5EC\uB123\uAE30\uB97C \uC4F0\uC138\uC694.",
    "err.inviteNotConnected": "\uCD08\uB300\uB97C \uBCF4\uB0B4\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4. \uADF8 \uB300\uD654\uB294 \uC9C0\uAE08 \uC5F0\uACB0\uB418\uC5B4 \uC788\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "err.inviteNotConnectedRetry": "\uCD08\uB300\uB97C \uBCF4\uB0B4\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4. \uADF8 \uB300\uD654\uB294 \uC9C0\uAE08 \uC5F0\uACB0\uB418\uC5B4 \uC788\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4 - \uB2E4\uC2DC \uC5F4\uACE0 \uC2DC\uB3C4\uD558\uC138\uC694.",
    "err.nobodyAccepted": "\uC544\uBB34\uB3C4 \uCD08\uB300\uB97C \uC218\uB77D\uD558\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uADF8\uB8F9\uC740 \uADF8\uB300\uB85C\uC785\uB2C8\uB2E4.",
    "err.noAudio": "\uC18C\uB9AC\uAC00 \uB179\uC74C\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4 - \uB9C8\uC774\uD06C \uAD8C\uD55C\uC744 \uD655\uC778\uD55C \uB4A4 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.",
    "err.voiceNeedsConnection": "\uC74C\uC131 \uBA54\uC2DC\uC9C0\uB97C \uBCF4\uB0B4\uB824\uBA74 \uD65C\uC131\uD654\uB41C \uC548\uC804\uD55C \uC5F0\uACB0\uC774 \uD544\uC694\uD569\uB2C8\uB2E4. \uB2E4\uC2DC \uC5F0\uACB0\uD55C \uB4A4 \uC2DC\uB3C4\uD558\uC138\uC694.",
