    "group.directLink": "\u0938\u0940\u0927\u093E \u092A\u0940\u092F\u0930-\u091F\u0942-\u092A\u0940\u092F\u0930 \u091C\u0941\u0921\u093C\u093E\u0935",
    "group.noDirectLink": "\u0905\u092D\u0940 \u0938\u0940\u0927\u093E \u091C\u0941\u0921\u093C\u093E\u0935 \u0928\u0939\u0940\u0902 \u0939\u0948 - \u092C\u0928\u0928\u0947 \u0924\u0915 \u0938\u0902\u0926\u0947\u0936 \u0915\u093F\u0938\u0940 \u0914\u0930 \u0938\u0926\u0938\u094D\u092F \u0915\u0947 \u091C\u093C\u0930\u093F\u090F \u091C\u093E\u0924\u0947 \u0939\u0948\u0902",
    "group.relayNote": "\u0915\u0941\u091B \u0938\u0926\u0938\u094D\u092F\u094B\u0902 \u0938\u0947 \u0905\u092D\u0940 \u0938\u0940\u0927\u093E \u091C\u0941\u0921\u093C\u093E\u0935 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u0909\u0928\u0915\u0947 \u0938\u0902\u0926\u0947\u0936 \u0915\u093F\u0938\u0940 \u0914\u0930 \u0938\u0926\u0938\u094D\u092F \u0938\u0947 \u0939\u094B\u0915\u0930 \u091C\u093E\u0924\u0947 \u0939\u0948\u0902, \u091C\u094B \u092F\u0939 \u0924\u094B \u0926\u0947\u0916 \u0938\u0915\u0924\u093E \u0939\u0948 \u0915\u093F \u092C\u093E\u0924\u091A\u0940\u0924 \u0939\u094B \u0930\u0939\u0940 \u0939\u0948, \u092A\u0930 \u0939\u0938\u094D\u0924\u093E\u0915\u094D\u0937\u0930 \u0915\u0947 \u0906\u0917\u0947 \u0928 \u092A\u0922\u093C \u0938\u0915\u0924\u093E \u0939\u0948 \u0928 \u0915\u0939\u0940 \u0939\u0941\u0908 \u092C\u093E\u0924 \u092C\u0926\u0932 \u0938\u0915\u0924\u093E \u0939\u0948\u0964 \u0938\u092E\u0942\u0939 \u0909\u0928\u094D\u0939\u0947\u0902 \u0938\u0940\u0927\u0947 \u091C\u094B\u0921\u093C\u0928\u0947 \u0915\u0940 \u0915\u094B\u0936\u093F\u0936 \u0915\u0930\u0924\u093E \u0930\u0939\u0924\u093E \u0939\u0948\u0964",
    "group.relayOnlyOff": "\u0915\u0947\u0935\u0932-\u0930\u093F\u0932\u0947 \u092E\u094B\u0921 \u092C\u0902\u0926 \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u0939\u0930 \u0938\u0926\u0938\u094D\u092F \u0906\u092A\u0938\u0947 \u0938\u0940\u0927\u0947 \u091C\u0941\u0921\u093C\u0924\u093E \u0939\u0948 \u0914\u0930 \u0906\u092A\u0915\u093E IP \u092A\u0924\u093E \u091C\u093E\u0928 \u0932\u0947\u0924\u093E \u0939\u0948 - \u0909\u0928\u092E\u0947\u0902 \u0935\u0947 \u092D\u0940 \u0939\u0948\u0902 \u091C\u093F\u0928\u094D\u0939\u0947\u0902 \u0915\u093F\u0938\u0940 \u0914\u0930 \u0928\u0947 \u092C\u0941\u0932\u093E\u092F\u093E\u0964 \u0905\u0917\u0930 \u092F\u0939 \u092F\u0939\u093E\u0901 \u092E\u093E\u092F\u0928\u0947 \u0930\u0916\u0924\u093E \u0939\u0948, \u0924\u094B \u0928\u0947\u091F\u0935\u0930\u094D\u0915 \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938 \u092E\u0947\u0902 \u0907\u0938\u0947 \u091A\u093E\u0932\u0942 \u0915\u0940\u091C\u093F\u090F\u0964",
    "group.memberOffline": "{name} \u0911\u092B\u093C\u0932\u093E\u0907\u0928 \u0939\u0948\u0902 \u0914\u0930 \u0938\u0902\u0926\u0947\u0936 \u0928\u0939\u0940\u0902 \u092A\u093E\u090F\u0901\u0917\u0947\u0964 \u0935\u0947 \u0905\u092C \u092D\u0940 \u0938\u0926\u0938\u094D\u092F \u0939\u0948\u0902 - \u0939\u091F\u093E\u0928\u0947 \u092A\u0930 \u0938\u092E\u0942\u0939 \u0915\u0940 \u0915\u0941\u0902\u091C\u093F\u092F\u093E\u0901 \u0928\u090F \u0938\u093F\u0930\u0947 \u0938\u0947 \u092C\u0928\u0924\u0940 \u0939\u0948\u0902\u0964",
    "group.joinNote": "\u092C\u093E\u0915\u093C\u0940 \u0938\u0926\u0938\u094D\u092F\u094B\u0902 \u0915\u094B \u092A\u0924\u093E \u091A\u0932\u0947\u0917\u093E \u0915\u093F \u0906\u092A \u0907\u0938 \u0938\u092E\u0942\u0939 \u092E\u0947\u0902 \u0939\u0948\u0902\u0964 \u092A\u0940\u091B\u0947 \u0915\u093E \u0915\u094B\u0908 \u0907\u0924\u093F\u0939\u093E\u0938 \u0928\u0939\u0940\u0902 \u0939\u0948 - \u0938\u092E\u0942\u0939 \u0916\u093C\u093E\u0932\u0940 \u0938\u0947 \u0936\u0941\u0930\u0942 \u0939\u094B\u0924\u093E \u0939\u0948\u0964",
    "group.inviteSentNote": "\u091C\u092C \u0924\u0915 \u0935\u0947 \u0938\u094D\u0935\u0940\u0915\u093E\u0930 \u0928\u0939\u0940\u0902 \u0915\u0930\u0924\u0947, \u0938\u092E\u0942\u0939 \u091A\u0932\u0924\u093E \u0930\u0939\u0924\u093E \u0939\u0948\u0964 \u0909\u0928\u0915\u0947 \u0932\u093F\u090F \u092A\u0940\u091B\u0947 \u0915\u093E \u0915\u094B\u0908 \u0907\u0924\u093F\u0939\u093E\u0938 \u0928\u0939\u0940\u0902 \u0939\u0948 - \u0935\u0947 \u0938\u093F\u0930\u094D\u092B\u093C \u0905\u092C \u0938\u0947 \u092D\u0947\u091C\u093E \u0917\u092F\u093E \u0926\u0947\u0916\u0947\u0902\u0917\u0947\u0964",
    "group.errNotCreated": "\u0938\u092E\u0942\u0939 \u0928\u0939\u0940\u0902 \u092C\u0928\u093E",
    "group.errNobodyAccepted": "\u0938\u092E\u092F \u0930\u0939\u0924\u0947 \u0915\u093F\u0938\u0940 \u0928\u0947 \u0928\u093F\u092E\u0902\u0924\u094D\u0930\u0923 \u0938\u094D\u0935\u0940\u0915\u093E\u0930 \u0928\u0939\u0940\u0902 \u0915\u093F\u092F\u093E\u0964",
    "group.errNothingSent": "\u0928 \u0915\u0941\u091B \u092D\u0947\u091C\u093E \u0917\u092F\u093E, \u0928 \u0915\u0941\u091B \u0938\u0924\u094D\u092F\u093E\u092A\u093F\u0924 \u0939\u0941\u0906\u0964 \u0907\u0938\u0947 \u092C\u0902\u0926 \u0915\u0940\u091C\u093F\u090F \u0914\u0930 \u0938\u092C\u0915\u0947 \u091C\u0941\u0921\u093C\u0928\u0947 \u092A\u0930 \u0926\u094B\u092C\u093E\u0930\u093E \u0915\u094B\u0936\u093F\u0936 \u0915\u0940\u091C\u093F\u090F\u0964",
    "group.errNotFormed": "\u092F\u0939 \u0938\u092E\u0942\u0939 \u0928\u0939\u0940\u0902 \u092C\u0928 \u0938\u0915\u093E\u0964",
    "group.errFull": "\u092F\u0939 \u0938\u092E\u0942\u0939 \u092D\u0930 \u091A\u0941\u0915\u093E \u0939\u0948\u0964",
    "group.errInviteFailed": "\u0928\u093F\u092E\u0902\u0924\u094D\u0930\u0923 \u0928\u0939\u0940\u0902 \u092D\u0947\u091C\u093E \u091C\u093E \u0938\u0915\u093E - \u0935\u0939 \u091A\u0948\u091F \u091C\u0941\u0921\u093C\u0940 \u0939\u0941\u0908 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964",
    "group.errNoMemberList": "\u0938\u092E\u0942\u0939 \u092C\u0928\u093E\u0928\u0947 \u0935\u093E\u0932\u0947 \u0928\u0947 \u0938\u0926\u0938\u094D\u092F\u094B\u0902 \u0915\u0940 \u0938\u0942\u091A\u0940 \u0915\u092D\u0940 \u092D\u0947\u091C\u0940 \u0939\u0940 \u0928\u0939\u0940\u0902\u0964",
    "group.errUnsignedList": "\u0938\u0926\u0938\u094D\u092F \u0938\u0942\u091A\u0940 \u092A\u0930 \u0938\u092E\u0942\u0939 \u092C\u0928\u093E\u0928\u0947 \u0935\u093E\u0932\u0947 \u0915\u0947 \u0939\u0938\u094D\u0924\u093E\u0915\u094D\u0937\u0930 \u0928\u0939\u0940\u0902 \u0939\u0948\u0902\u0964 \u0926\u094B\u092C\u093E\u0930\u093E \u0915\u094B\u0936\u093F\u0936 \u092E\u0924 \u0915\u0940\u091C\u093F\u090F - \u0909\u0928\u094D\u0939\u0947\u0902 \u092C\u0924\u093E\u0907\u090F\u0964",
    "group.errNotOwner": "\u0938\u092E\u0942\u0939 \u0915\u0947 \u0938\u094D\u0935\u093E\u092E\u0940 \u0915\u0947 \u0905\u0932\u093E\u0935\u093E \u0915\u093F\u0938\u0940 \u0914\u0930 \u0928\u0947 \u0938\u0926\u0938\u094D\u092F \u092C\u0926\u0932\u0928\u0947 \u0915\u0940 \u0915\u094B\u0936\u093F\u0936 \u0915\u0940\u0964",
    "hdr.tagline": "\u090F\u0902\u0921-\u091F\u0942-\u090F\u0902\u0921 \u090F\u0928\u094D\u0915\u094D\u0930\u093F\u092A\u094D\u091F\u0947\u0921",
    "hdr.netSettings": "\u0909\u0928\u094D\u0928\u0924 \u0928\u0947\u091F\u0935\u0930\u094D\u0915 \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938",
    "hdr.netSettingsTitle": "\u0909\u0928\u094D\u0928\u0924 \u0928\u0947\u091F\u0935\u0930\u094D\u0915 \u0938\u0947\u091F\u093F\u0902\u0917\u094D\u0938 (STUN/TURN)",
