    "err.securityValidation": "\u0938\u0941\u0930\u0915\u094D\u0937\u093E \u091C\u093E\u0901\u091A \u0935\u093F\u092B\u0932 - \u0939\u092E\u0932\u093E \u0939\u094B \u0938\u0915\u0924\u093E \u0939\u0948",
    "err.retiredQr": "\u092F\u0939 QR \u0910\u0938\u0947 \u092A\u0941\u0930\u093E\u0928\u0947 \u092A\u094D\u0930\u093E\u0930\u0942\u092A \u0915\u093E \u0939\u0948 \u091C\u093F\u0938\u0938\u0947 \u0928\u093F\u092E\u0902\u0924\u094D\u0930\u0923 \u0928\u0939\u0940\u0902 \u092D\u0947\u091C\u093E \u091C\u093E \u0938\u0915\u093E\u0964 \u0938\u093E\u092E\u0928\u0947 \u0935\u093E\u0932\u0947 \u0938\u0947 \u0928\u092F\u093E \u092C\u0928\u0935\u093E\u0907\u090F, \u092F\u093E \u0915\u0949\u092A\u0940-\u092A\u0947\u0938\u094D\u091F \u0915\u0940\u091C\u093F\u090F\u0964",
    "err.compressedQrNote": "\u0938\u0902\u0915\u094D\u0937\u0947\u092A \u0915\u0947 \u0932\u093F\u090F \u0926\u092C\u093E\u092F\u093E \u0939\u0941\u0906 QR \u0915\u092D\u0940-\u0915\u092D\u0940 SDP \u091B\u094B\u0921\u093C \u0926\u0947\u0924\u093E \u0939\u0948\u0964 \u091C\u0941\u0921\u093C\u093E\u0935 \u0928 \u092C\u0928\u0947 \u0924\u094B \u0915\u0949\u092A\u0940-\u092A\u0947\u0938\u094D\u091F \u0915\u0940\u091C\u093F\u090F\u0964",
    "err.inviteNotConnected": "\u0928\u093F\u092E\u0902\u0924\u094D\u0930\u0923 \u0928\u0939\u0940\u0902 \u092D\u0947\u091C\u093E \u091C\u093E \u0938\u0915\u093E\u0964 \u0935\u0939 \u091A\u0948\u091F \u0905\u092D\u0940 \u091C\u0941\u0921\u093C\u0940 \u0939\u0941\u0908 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964",
