    "qr.showSubtitleFrames": "\u05DE\u05E1\u05DA \u05DE\u05DC\u05D0 \xB7 \u05EA\u05E0\u05D5 \u05DC\u05E2\u05DE\u05D9\u05EA \u05DC\u05E1\u05E8\u05D5\u05E7 \u05D0\u05EA \u05DB\u05DC {frames} \u05D4\u05E4\u05E8\u05D9\u05D9\u05DE\u05D9\u05DD",
    "notify.enabledBody": "\u05D4\u05D4\u05EA\u05E8\u05D0\u05D5\u05EA \u05D4\u05D5\u05E4\u05E2\u05DC\u05D5! \u05EA\u05E7\u05D1\u05DC\u05D5 \u05D4\u05EA\u05E8\u05D0\u05D5\u05EA \u05E2\u05DC \u05D4\u05D5\u05D3\u05E2\u05D5\u05EA \u05D7\u05D3\u05E9\u05D5\u05EA.",
    "notify.workingBody": "\u05D4\u05D4\u05EA\u05E8\u05D0\u05D5\u05EA \u05E2\u05D5\u05D1\u05D3\u05D5\u05EA! \u05EA\u05E7\u05D1\u05DC\u05D5 \u05D4\u05EA\u05E8\u05D0\u05D5\u05EA \u05E2\u05DC \u05D4\u05D5\u05D3\u05E2\u05D5\u05EA \u05D7\u05D3\u05E9\u05D5\u05EA.",
