    "desktop.protocolViolation": "\u0637\u0631\u0641 \u0645\u0642\u0627\u0628\u0644 \u067E\u06CC\u0634 \u0627\u0632 \u062A\u0623\u06CC\u06CC\u062F \u0634\u0645\u0627 \u0627\u062F\u0639\u0627\u06CC \u062A\u0623\u06CC\u06CC\u062F \u06A9\u062F \u0631\u0627 \u06A9\u0631\u062F. \u0628\u0631\u0627\u06CC \u0627\u06CC\u0645\u0646\u06CC \u0642\u0637\u0639 \u0645\u06CC\u200C\u0634\u0648\u062F.",
