    "desktop.ice.persistDesc": "\u0628\u0647\u200C\u0635\u0648\u0631\u062A \u0645\u062D\u0644\u06CC \u0631\u0648\u06CC \u0647\u0645\u06CC\u0646 \u062F\u0633\u062A\u06AF\u0627\u0647 \u0630\u062E\u06CC\u0631\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F. \u0628\u0631\u0627\u06CC \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0641\u0642\u0637 \u062F\u0631 \u0627\u06CC\u0646 \u0646\u0634\u0633\u062A\u060C \u062E\u0627\u0645\u0648\u0634 \u0628\u06AF\u0630\u0627\u0631\u06CC\u062F.",
    "desktop.group.leaveNote": "\u0628\u0647 \u0628\u0642\u06CC\u0647\u0654 \u0627\u0639\u0636\u0627 \u0627\u0637\u0644\u0627\u0639 \u062F\u0627\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F \u06A9\u0647 \u062E\u0627\u0631\u062C \u0634\u062F\u0647\u200C\u0627\u06CC\u062F. \u067E\u0633 \u0627\u0632 \u0622\u0646 \u0686\u06CC\u0632\u06CC \u0627\u0632 \u0627\u06CC\u0646 \u06AF\u0631\u0648\u0647 \u0631\u0648\u06CC \u0627\u06CC\u0646 \u062F\u0633\u062A\u06AF\u0627\u0647 \u0646\u0645\u06CC\u200C\u0645\u0627\u0646\u062F - \u0647\u06CC\u0686 \u0633\u0631\u0648\u0631\u06CC \u0646\u0633\u062E\u0647\u200C\u0627\u06CC \u0646\u062F\u0627\u0631\u062F \u06A9\u0647 \u0628\u062A\u0648\u0627\u0646 \u0627\u0632 \u0622\u0646 \u0628\u0627\u0632\u06AF\u0634\u062A\u060C \u067E\u0633 \u0628\u0647 \u062F\u0639\u0648\u062A \u062A\u0627\u0632\u0647 \u0646\u06CC\u0627\u0632 \u062E\u0648\u0627\u0647\u06CC\u062F \u062F\u0627\u0634\u062A.",
    "desktop.sec.ecdsaOk": "\u0627\u0645\u0636\u0627\u06CC \u0628\u0633\u062A\u0647\u0654 \u06A9\u0644\u06CC\u062F \u0637\u0631\u0641 \u0645\u0642\u0627\u0628\u0644 \u0647\u0646\u06AF\u0627\u0645 \u062F\u0633\u062A\u200C\u062F\u0627\u062F\u0646 \u0628\u0631\u0631\u0633\u06CC \u0634\u062F (ECDSA P-384 / SHA-384)",
