    "desktop.sec.coverOff": "\u0645\u0648\u0644\u062F \u062A\u0631\u0627\u0641\u06CC\u06A9 \u067E\u0648\u0634\u0634\u06CC \u062F\u0631 \u062D\u0627\u0644 \u0627\u062C\u0631\u0627 \u0646\u06CC\u0633\u062A",
