    "ice.errInvalid": "\u0633\u0631\u0648\u0631 \u06A9\u06CC \u062A\u0631\u062A\u06CC\u0628 \u063A\u0644\u0637 \u06C1\u06D2",
    "update.title": "\u062A\u0627\u0632\u06C1 \u06A9\u0627\u0631\u06CC \u062F\u0633\u062A\u06CC\u0627\u0628 \u06C1\u06D2",
    "update.desc": "\u200FSecureBit \u06A9\u0627 \u0646\u06CC\u0627 \u0646\u0633\u062E\u06C1 \u0645\u0644\u0627 \u06C1\u06D2\u06D4",
