    "sec.forwardSecrecy": "\u0645\u06A9\u0645\u0644 \u0641\u0627\u0631\u0648\u0631\u0688 \u0633\u06CC\u06A9\u0631\u0633\u06CC",
    "sec.metadataProtection": "\u0645\u06CC\u0679\u0627 \u0688\u06CC\u0679\u0627 \u06A9\u0627 \u062A\u062D\u0641\u0638",
