    "chat.groupChats": "\u06AF\u0631\u0648\u06C1\u06CC \u06AF\u0641\u062A\u06AF\u0648",
    "chat.secureChat": "\u0645\u062D\u0641\u0648\u0638 \u06AF\u0641\u062A\u06AF\u0648",
