    "chat.rename": "\u06AF\u0641\u062A\u06AF\u0648 \u06A9\u0627 \u0646\u0627\u0645 \u0628\u062F\u0644\u06CC\u06BA (\u0635\u0631\u0641 \u0645\u0642\u0627\u0645\u06CC)",
    "chat.renameHint": "\u0646\u0627\u0645 \u0628\u062F\u0644\u0646\u06D2 \u06A9\u06D2 \u0644\u06CC\u06D2 \u062F\u0648 \u0628\u0627\u0631 \u062F\u0628\u0627\u0626\u06CC\u06BA",
    "chat.localLabel": "\u0645\u0642\u0627\u0645\u06CC \u0639\u0646\u0648\u0627\u0646 \xB7 \u0635\u0631\u0641 \u0627\u0633\u06CC \u0622\u0644\u06D2 \u067E\u0631 \u0645\u062D\u0641\u0648\u0638",
